-- ************************************** ERP.EKPO
CREATE TABLE ERP.EKPO
(
 EBELN char(10) NOT NULL COMMENT 'Unique identifier for the purchasing document; links to the EKKO table.',
 EBELP char(5) NOT NULL COMMENT 'Sequential number of the item within the purchasing document.',
 MATNR char(18) COMMENT 'Identifier for the material; links to the MARA table.',
 MENGE decimal(13,3) COMMENT 'Quantity Ordered',
 KOSTL char(10) NOT NULL COMMENT 'Unique identifier for the cost center within the controlling area.',

 CONSTRAINT EBELN PRIMARY KEY ( EBELN, EBELP ),
 CONSTRAINT FK_1 FOREIGN KEY ( KOSTL ) REFERENCES ERP.CSKS ( KOSTL )
)
COMMENT = 'Stores detailed information for each item within purchasing documents such as purchase orders, contracts, and scheduling agreements.';
